func TestEnumPushOrdersRequestStatus(t *testing.T) {
	t.Run("NewFromString_placed", func(t *testing.T) {
		t.Parallel()
		val, err := NewPushOrdersRequestStatusFromString("placed")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, PushOrdersRequestStatus("placed"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_cancelled", func(t *testing.T) {
		t.Parallel()
		val, err := NewPushOrdersRequestStatusFromString("cancelled")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, PushOrdersRequestStatus("cancelled"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_fulfilled", func(t *testing.T) {
		t.Parallel()
		val, err := NewPushOrdersRequestStatusFromString("fulfilled")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, PushOrdersRequestStatus("fulfilled"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_refunded", func(t *testing.T) {
		t.Parallel()
		val, err := NewPushOrdersRequestStatusFromString("refunded")
		assert.NoError(t, err, "valid enum value should not return error")
		assert.Equal(t, PushOrdersRequestStatus("refunded"), val, "enum value should match expected wire value")
	})

	t.Run("NewFromString_Invalid", func(t *testing.T) {
		_, err := NewPushOrdersRequestStatusFromString("invalid_value_that_does_not_exist")
		assert.Error(t, err)
	})

	t.Run("Ptr", func(t *testing.T) {
		val, err := NewPushOrdersRequestStatusFromString("placed")
		assert.NoError(t, err)
		ptr := val.Ptr()
		assert.NotNil(t, ptr)
		assert.Equal(t, val, *ptr)
	})
}

func TestExtraPropertiesCommerceOrderItem(t *testing.T) {
	t.Run("GetExtraProperties", func(t *testing.T) {
		t.Parallel()
		obj := &CommerceOrderItem{}
		// Should not panic when calling GetExtraProperties()
		defer func() {
			if r := recover(); r != nil {
				t.Errorf("GetExtraProperties() panicked: %v", r)
			}
		}()
		extraProps := obj.GetExtraProperties()
		// Result can be nil or an empty/non-empty map
		_ = extraProps
	})

	t.Run("GetExtraProperties_NilReceiver", func(t *testing.T) {
		t.Parallel()
		var obj *CommerceOrderItem
		extraProps := obj.GetExtraProperties()
		assert.Nil(t, extraProps, "nil receiver should return nil without panicking")
	})
}

